{"command": "cd /workspace && python3 - <<'EOF'
import sqlite3, re, os
con = sqlite3.connect('cms/ridgeline_cms.db')
con.row_factory = sqlite3.Row
cur = con.cursor()

# expected subject data per case
def data_for(sid):
    d = {}
    cur.execute("SELECT * FROM subjects WHERE subject_id=?", (sid,))
    s = cur.fetchone()
    d['name'] = s['full_name']; d['dob'] = s['dob']
    cur.execute("SELECT address, city, state FROM address_history WHERE subject_id=?", (sid,))
    d['addrs'] = {f"{r['address']}, {r['city']}, {r['state']}" for r in cur.fetchall()}
    cur.execute("SELECT number FROM phones WHERE subject_id=?", (sid,))
    d['phones'] = {r['number'] for r in cur.fetchall()}
    cur.execute("SELECT plate FROM vehicles WHERE subject_id=?", (sid,))
    d['plates'] = {r['plate'] for r in cur.fetchall()}
    return d

cases = {f"RIG-2026-100{i}": 4100+i for i in range(1,3)}
cases.update({f"RIG-2026-10{k}": v for k,v in zip(range(3,13), range(4103,4113))})

problems = 0
for case, sid in cases.items():
    d = data_for(sid)
    fname = f"out/{case}.md"
    if not os.path.exists(fname):
        print(f"{case}: MISSING REPORT"); problems += 1; continue
    text = open(fname).read()
    # every address for the subject should appear (addresses written as "addr, city, ST")
    for a in d['addrs']:
        addr, city, state = [x.strip() for x in a.rsplit(',',2)]
        if addr not in text:
            print(f"{case}: address not found verbatim: {a}"); problems += 1
    for p in d['phones']:
        if p not in text:
            print(f"{case}: phone not found: {p}"); problems += 1
    for pl in d['plates']:
        if pl not in text:
            print(f"{case}: plate not found: {pl}"); problems += 1
    if d['dob'] not in text:
        print(f"{case}: DOB not found: {d['dob']}"); problems += 1
print("cross-check complete; issues:", problems)
EOF"}
